        row3_super: "\u05D1\u05E1\u05D5\u05E4\u05E8 \u2014 \u05E2\u05D5\u05D3 \u05E4\u05E8\u05D9\u05D8 \u05D1\u05E2\u05D2\u05DC\u05D4"
