          herbal: { label: "\u05EA\u05DB\u05E9\u05D9\u05E8\u05D9 \u05E6\u05DE\u05D7\u05D9\u05DD", doc: "\u05DE\u05D0\u05D5\u05DE\u05EA: \u05E8\u05D9\u05E9\u05D5\u05DD \u05D1\u05DE\u05E8\u05E9\u05DD \u05D4\u05EA\u05DE\u05E8\u05D5\u05E7\u05D9\u05DD." },
          candles: { label: "\u05E0\u05E8\u05D5\u05EA \u05D5\u05D0\u05E8\u05D5\u05DE\u05D4", note: "\u05D1\u05E7\u05D8\u05D2\u05D5\u05E8\u05D9\u05D4 \u05D4\u05D6\u05D5 \u05D0\u05D9\u05DF \u05DE\u05E1\u05DC\u05D5\u05DC \u05DC\u05EA\u05D2 \u2014 \u05E4\u05E9\u05D5\u05D8 \u05D0\u05D9\u05DF \u05DE\u05E1\u05DE\u05DA \u05DC\u05D0\u05DE\u05EA, \u05D5\u05D6\u05D4 \u05D1\u05E1\u05D3\u05E8 \u05D2\u05DE\u05D5\u05E8." }
